-- Run only against Test after migration, inside a transaction rolled back below.
do $$
declare admin_id uuid; sid uuid; gid uuid; mid uuid; cancelled uuid; lid uuid; reportid uuid; aid uuid:=gen_random_uuid(); opts jsonb; p jsonb; old_revision text; failed boolean; frozen_hash text;
begin
 select id into admin_id from public.profiles where role='admin' and active order by created_at limit 1;
 if admin_id is null then raise exception 'Test admin fixture unavailable';end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true);
 insert into public.seasons(code,name,status) values('issue-37-transaction-test','封存整合測試（交易回滾，不公開）','active') returning id into sid;
 insert into public.groups(season_id,code,name) values(sid,'A','A 組') returning id into gid;
 insert into public.teams(team_code,name,short_name) values('I37-TX-A','合成測試 A','合成 A'),('I37-TX-B','合成測試 B','合成 B');
 insert into public.season_teams(season_id,team_id,group_id,display_name,display_order) select sid,id,gid,name,row_number() over(order by team_code) from public.teams where team_code in ('I37-TX-A','I37-TX-B');
 insert into public.players(team_id,name,status,roster_role,display_order,public_visible,season_code) select id,'合成甲','active','player',0,true,'issue-37-transaction-test' from public.teams where team_code='I37-TX-A';
 insert into public.matches(season_id,group_id,match_code,match_date,match_time,home_team_id,away_team_id) select sid,gid,'I37-TX-M1','2026-01-01','10:00',a.id,b.id from public.teams a,public.teams b where a.team_code='I37-TX-A' and b.team_code='I37-TX-B' returning id into mid;
 opts=jsonb_build_object('rules_text','測試規則，非正式規程','rules_source','合成測試','final_rankings','[]'::jsonb,'final_rankings_note','主辦未提供最終名次（測試）','exceptions','[]'::jsonb,'all_stages_closed',true,'results_confirmed',true,'public_scope_confirmed',true);
 p=public.preview_season_archive('issue-37-transaction-test',opts);
 if (p->>'eligible')::boolean or not exists(select 1 from jsonb_array_elements(p->'blockers') x where x->>'code'='unresolved_match') then raise exception 'unresolved match must block';end if;
 update public.matches set status='final' where id=mid;
 p=public.preview_season_archive('issue-37-transaction-test',opts);
 if (p->>'eligible')::boolean then raise exception 'missing result must block';end if;
 insert into public.match_results(match_id,home_score,away_score,published) values(mid,3,0,false);
 p=public.preview_season_archive('issue-37-transaction-test',opts);
 if (p->>'eligible')::boolean then raise exception 'unpublished result must block';end if;
 update public.match_results set published=true where match_id=mid;
 insert into public.daily_report_links(season_id,match_date,created_by) values(sid,'2026-01-01',admin_id) returning id into lid;
 insert into public.referee_reports(match_id,link_id,home_score,away_score) values(mid,lid,3,0) returning id into reportid;
 p=public.preview_season_archive('issue-37-transaction-test',opts);
 if (p->>'eligible')::boolean then raise exception 'pending report must block';end if;
 update public.referee_reports set disposition='reviewed' where id=reportid;
 insert into public.matches(season_id,group_id,match_code,match_date,match_time,home_team_id,away_team_id,status) select sid,gid,'I37-TX-M2','2026-01-02','10:00',a.id,b.id,'cancelled' from public.teams a,public.teams b where a.team_code='I37-TX-A' and b.team_code='I37-TX-B' returning id into cancelled;
 p=public.preview_season_archive('issue-37-transaction-test',opts);
 if (p->>'eligible')::boolean then raise exception 'cancelled without explanation must block';end if;
 opts=jsonb_set(opts,'{exceptions}','[{"match_code":"I37-TX-M2","reason":"主辦確認取消（合成測試）"}]');
 p=public.preview_season_archive('issue-37-transaction-test',opts);
 if not (p->>'eligible')::boolean then raise exception 'valid synthetic season eligibility failed: %',p->'blockers';end if;
 if p#>'{content,league,roster}'<>'[]'::jsonb then raise exception 'archive roster must be excluded';end if;
 old_revision=p->>'revision_hash';
 update public.teams set name='合成測試 A 改名' where team_code='I37-TX-A';
 failed=false;begin perform public.reserve_season_archive('issue-37-transaction-test',opts,old_revision,aid);exception when sqlstate 'PT409' then failed=true;end;
 if not failed then raise exception 'stale preview accepted';end if;
 p=public.preview_season_archive('issue-37-transaction-test',opts);old_revision=p->>'revision_hash';
 perform public.reserve_season_archive('issue-37-transaction-test',opts,old_revision,aid);
 perform public.reserve_season_archive('issue-37-transaction-test',opts,old_revision,aid);
 failed=false;begin update public.matches set published=false where id=mid;exception when sqlstate '55000' then failed=true;end;if not failed then raise exception 'frozen match mutable';end if;
 failed=false;begin update public.match_results set home_score=2,away_score=1 where match_id=mid;exception when sqlstate '55000' then failed=true;end;if not failed then raise exception 'frozen result mutable';end if;
 failed=false;begin insert into public.matches(season_id,group_id,match_code,match_date,match_time,home_team_id,away_team_id) select sid,gid,'I37-TX-NEW','2026-01-03','10:00',a.id,b.id from public.teams a,public.teams b where a.team_code='I37-TX-A' and b.team_code='I37-TX-B';exception when sqlstate '55000' then failed=true;end;if not failed then raise exception 'frozen match insertion accepted';end if;
 failed=false;begin update public.referee_reports set disposition='pending' where id=reportid;exception when sqlstate '55000' then failed=true;end;if not failed then raise exception 'frozen report mutable';end if;
 failed=false;begin delete from public.season_teams where season_id=sid;exception when sqlstate '55000' then failed=true;end;if not failed then raise exception 'frozen membership deletable';end if;
 -- Shared team identity may be reused next season; frozen display content stays unchanged.
 select content_hash into frozen_hash from public.season_archives where id=aid;
 update public.teams set name='新賽季共用隊伍改名' where team_code='I37-TX-A';
 if public.get_public_league('issue-37-transaction-test') is distinct from (select current_projection from public.season_archives where id=aid) then raise exception 'frozen public data changed with live team';end if;
 if jsonb_array_length(public.get_public_league('issue-37-transaction-test')->'roster')<>1 then raise exception 'existing public roster changed by archival';end if;
 if public.get_public_season_archives('issue-37-transaction-test')<>'[]'::jsonb then raise exception 'pending archive publicly listed';end if;
 perform public.confirm_season_archive(aid,frozen_hash,'issue-37-transaction-test/'||aid||'-'||frozen_hash||'.json');
 perform public.confirm_season_archive(aid,frozen_hash,'issue-37-transaction-test/'||aid||'-'||frozen_hash||'.json');
 if jsonb_array_length(public.get_public_season_archives('issue-37-transaction-test'))<>1 then raise exception 'published archive missing';end if;
 failed=false;begin update public.season_archives set public_content='{}' where id=aid;exception when sqlstate '55000' then failed=true;end;if not failed then raise exception 'published archive mutable';end if;
 failed=false;begin delete from public.season_archives where id=aid;exception when sqlstate '55000' then failed=true;end;if not failed then raise exception 'archive deletable';end if;
 if has_function_privilege('anon','public.reserve_season_archive(text,jsonb,text,uuid)','execute') or has_function_privilege('authenticated','public.confirm_season_archive(uuid,text,text)','execute') then raise exception 'privileged RPC grants unsafe';end if;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{}',true);
 failed=false;begin perform public.preview_season_archive('issue-37-transaction-test',opts);exception when insufficient_privilege then failed=true;end;if not failed then raise exception 'anonymous preview allowed';end if;
 raise notice 'issue-37 transactional assertions passed';
end $$;
